<template><div class="auth-page"><section class="auth-card"><h1>Choose a new password</h1><form @submit.prevent="submit"><label>New password<input v-model="password" type="password" minlength="8" maxlength="128" required autocomplete="new-password"></label><label>Confirm password<input v-model="confirm" type="password" required autocomplete="new-password"></label><p class="hint">At least 8 characters, including a letter and a number.</p><p v-if="error" class="error">{{error}}</p><button :disabled="busy">{{busy?'Resetting…':'Reset password'}}</button></form></section></div></template>
<script setup lang="ts">import{ref}from'vue';import{useRoute,useRouter}from'vue-router';import{AuthApiError,resetPassword}from'@/api/auth';import{useAuth}from'@/composables/useAuth';const password=ref(''),confirm=ref(''),error=ref(''),busy=ref(false),route=useRoute(),router=useRouter(),{clearAuthentication}=useAuth();async function submit(){error.value='';if(password.value!==confirm.value){error.value='Passwords do not match.';return}busy.value=true;try{await resetPassword(String(route.query.token||''),password.value,confirm.value);clearAuthentication();await router.push({name:'login',query:{passwordChanged:'1'}})}catch(e){error.value=e instanceof AuthApiError?e.message:'Unable to reset password.'}finally{busy.value=false}}</script>
<style scoped>.auth-page{display:grid;place-items:center;min-height:60vh}.auth-card{width:min(400px,100%);border:1px solid var(--color-border);border-radius:var(--radius-lg);padding:2rem}form,label{display:flex;flex-direction:column;gap:.75rem}input,button{padding:.8rem;border-radius:var(--radius-md)}input{border:1px solid var(--color-border)}button{border:0;background:var(--color-primary);color:white}.hint{font-size:.8rem;color:var(--color-text-secondary)}.error{color:#b42318}</style>
